'use strict';

const fs = require('fs');
const path = require('path');

const WORKSPACE = __dirname;
const MANIFEST_NAME = 'backup-manifest.json';

function isRegularFile(name) {
  try {
    return fs.statSync(path.join(WORKSPACE, name)).isFile();
  } catch (err) {
    return false;
  }
}

function collectFiles() {
  return fs
    .readdirSync(WORKSPACE)
    .filter((name) => !name.startsWith('.'))
    .filter((name) => name !== MANIFEST_NAME)
    .filter((name) => isRegularFile(name))
    .sort();
}

function main() {
  const files = collectFiles();
  const manifestPath = path.join(WORKSPACE, MANIFEST_NAME);
  fs.writeFileSync(manifestPath, JSON.stringify({ files }, null, 2) + '\n');
  console.log(`Wrote ${MANIFEST_NAME} with ${files.length} file(s):`);
  files.forEach((name) => console.log(`  ${name}`));
}

main();

