  const isRegularFile = (name) => {
    try {
      return fs.statSync(path.join(workspace, name)).isFile();
    } catch (err) {
      return false;
    }
  };

  const files = fs
    .readdirSync(workspace)
    .filter((name) => !name.startsWith('.'))
    .filter((name) => name !== manifestName)
    .filter((name) => isRegularFile(name))
    .sort();

  fs.writeFileSync(manifestPath, JSON.stringify({ files }, null, 2) + '\n');

  console.log(`Wrote ${manifestName} with ${files.length} file(s):`);
  files.forEach((name) => console.log(`  ${name}`));
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});

