  ['files sorted ascending', JSON.stringify(manifest.files) === JSON.stringify([...manifest.files].sort())],
  ['hidden files excluded', !manifest.files.some((n) => n.startsWith('.'))],
  ['manifest excludes itself', !manifest.files.includes('backup-manifest.json')],
  ['matches workspace listing', JSON.stringify(manifest.files) === JSON.stringify(expected)],
  ['no directories listed', manifest.files.every((n) => fs.statSync(path.join(ws, n)).isFile())],
];

for (const [name, ok] of checks) console.log((ok ? 'PASS' : 'FAIL') + ' - ' + name);
console.log('\nfiles = ' + JSON.stringify(manifest.files));
process.exit(checks.every((c) => c[1]) ? 0 : 1);

